        statuses = [
            Status(name='Новый', description='Термин на проверке'),
            Status(name='Одобрен', description='Термин одобрен модератором'),
            Status(name='Отклонён', description='Термин отклонён'),
            Status(name='Опубликован', description='Термин опубликован на сайте')
        ]
        db.session.add_all(statuses)
        db.session.commit()
        
        # --- 1. Создание типов связей ---
        rel_synonym = RelationType(type_name="Синоним")
        rel_antonym = RelationType(type_name="Антоним")
        rel_related = RelationType(type_name="Родственное понятие")
        db.session.add_all([rel_synonym, rel_antonym, rel_related])
        db.session.commit()
        print("Типы связей созданы.")

        # --- Вспомогательная функция для создания термина ---
        def create_term(title, transcription, origin, grammar, definitions_data, categories=None, year_fixed=None, last_year_fixed=None):
            term = Term(
                term_name=title,
                transcription=transcription,
                origin_word=origin,
                grammar_notes=grammar,
                year_fixed=year_fixed,
                last_year_fixed=last_year_fixed,
                user_id=default_user.id,
                status_id=statuses[3].id  # Опубликован
            )
            db.session.add(term)
            db.session.flush()

            for idx, def_data in enumerate(definitions_data):
                definition = Definition(
                    term_id=term.id,
                    definition_text=def_data['text'],
                    style_note=def_data.get('style', '')
                )
                db.session.add(definition)
                db.session.flush()

                for ex_text in def_data.get('examples', []):
                    example = Example(definition_id=definition.id, example_text=ex_text)
                    db.session.add(example)
            return term

