        t_mentor = create_term("Ментор", "[м'э́нтар]", "mentor (англ.)", "сущ., м.р., одуш.", [{"text": "Наставник, помогающий в развитии.", "examples": ["Ментор проводит код-ревью.", "Ищу ментора по архитектуре."], "style": "корп."}], last_year_fixed=2026)
        t_intern = create_term("Интерн", "[инт'э́рн]", "intern (англ.)", "сущ., м.р., одуш.", [{"text": "Стажёр в компании.", "examples": ["Интерн закрыл таск.", "Интерн переходит в штат."], "style": "корп."}], last_year_fixed=2026)
        t_onboarding = create_term("Онбординг", "[анбóрд'инк]", "onboarding (англ.)", "сущ., м.р., неодуш.", [{"text": "Процесс адаптации нового сотрудника.", "examples": ["Онбординг длится месяц.", "Автоматизируй онбординг."], "style": "корп."}], last_year_fixed=2026)
        t_offboarding = create_term("Оффбординг", "[афбóрд'инк]", "offboarding (англ.)", "сущ., м.р., неодуш.", [{"text": "Процесс увольнения и передачи дел.", "examples": ["Оффбординг прошёл гладко.", "Оформляй оффбординг по чек-листу."], "style": "корп."}], last_year_fixed=2026)
        t_performance = create_term("Перфоманс", "[п'ирф'о́рманс]", "performance (англ.)", "сущ., м.р., неодуш.", [{"text": "Оценка эффективности работы.", "examples": ["Перфоманс-ревью в конце квартала.", "Перфоманс вырос после обучения."], "style": "корп."}], last_year_fixed=2026)
        t_review = create_term("Ревью", "[р'ив'ю́]", "review (англ.)", "сущ., ср.р., нескл.", [{"text": "Обзор, проверка или оценка.", "examples": ["Провели ревью архитектуры.", "Ревью показало риски."], "style": "проф."}], last_year_fixed=2026)

        db.session.commit()
        print("Все 100 терминов созданы.")

        # --- 3. Создание семантических связей ---
        relations = [
            # СИНОНИМЫ
            (t_bug, t_error, rel_synonym),
            (t_lag, t_freeze, rel_synonym),
            (t_fix, t_debug, rel_related),
            (t_pilit, t_debug, rel_synonym),
            (t_hardcode, t_kostyl, rel_synonym),
            
            # АНТОНИМЫ
            (t_jun, t_senior, rel_antonym),
            (t_backend, t_frontend, rel_antonym),
            (t_deploy, t_rollback, rel_antonym),
            (t_uptime, t_downtime, rel_antonym),
            (t_hardcode, t_config, rel_antonym),
            (t_kostyl, t_refactor, rel_antonym),
            (t_crash, t_uptime, rel_antonym),
            (t_skip, t_solve, rel_antonym),
            (t_local, t_prod, rel_antonym),
            (t_mono, t_micro, rel_antonym),
            (t_minor, t_major, rel_antonym),
            (t_onboarding, t_offboarding, rel_antonym),
            (t_hardskill, t_softskill, rel_antonym),
        ]

        for source, target, r_type in relations:
            relation = TermRelation(term_1_id=source.id, term_2_id=target.id, relation_type_id=r_type.id)
            db.session.add(relation)
            if r_type.type_name in ["Синоним", "Антоним"]:
                reverse = TermRelation(term_1_id=target.id, term_2_id=source.id, relation_type_id=r_type.id)
                db.session.add(reverse)
                
        db.session.commit()
        print("Семантические связи созданы.")
